    // ── Degenerate domain round-trips in CoordKind ────────────────────────

    /// CoordKind with degenerate domain [5.0, 5.0] (single-value data).
    #[test]
    fn cartesian_degenerate_domain_round_trips() {
        let coord = CoordKind::Cartesian {
            x_domain: Some((5.0, 5.0)),
            y_domain: Some((0.0, 0.0)),
            expand: true,
            clip: true,
        };
        let json = serde_json::to_string(&coord).expect("serialize");
        let back: CoordKind = serde_json::from_str(&json).expect("deserialize");
        match back {
            CoordKind::Cartesian { x_domain, y_domain, .. } => {
                let (x_lo, x_hi) = x_domain.unwrap();
                assert_eq!(x_lo, 5.0);
                assert_eq!(x_hi, 5.0);
                let (y_lo, y_hi) = y_domain.unwrap();
                assert_eq!(y_lo, 0.0);
                assert_eq!(y_hi, 0.0);
            }
            other => panic!("expected Cartesian, got {other:?}"),
        }
    }

    /// CoordKind with very large domain values (1e300).
    #[test]
    fn cartesian_extreme_domain_values_round_trip() {
        let coord = CoordKind::Cartesian {
            x_domain: Some((-1e300, 1e300)),
            y_domain: Some((1e-300, 1e300)),
            expand: false,
            clip: false,
        };
        let json = serde_json::to_string(&coord).expect("serialize extreme");
        let back: CoordKind = serde_json::from_str(&json).expect("deserialize extreme");
        match back {
            CoordKind::Cartesian { x_domain, y_domain, .. } => {
                let (x_lo, x_hi) = x_domain.unwrap();
                assert!((x_lo - (-1e300)).abs() < 1e290);
                assert!((x_hi - 1e300).abs() < 1e290);
                let (y_lo, _) = y_domain.unwrap();
                assert!(y_lo > 0.0 && y_lo < 1e-299);
            }
            other => panic!("expected Cartesian, got {other:?}"),
        }
    }

    /// CoordKind with NaN in domain (what if scale domain computation fails).
    #[test]
    fn cartesian_nan_domain_serializes_as_null() {
        let coord = CoordKind::Cartesian {
            x_domain: Some((f64::NAN, f64::NAN)),
            y_domain: None,
            expand: true,
            clip: true,
        };
        let json = serde_json::to_string(&coord).expect("serialize NaN domain");
        assert!(
            !json.contains("NaN"),
            "NaN domain must not appear as literal 'NaN' in JSON: {json}"
        );
    }

    /// CoordKind with negative zero domain endpoint.
    #[test]
    fn cartesian_negative_zero_domain_round_trips() {
        let coord = CoordKind::Cartesian {
            x_domain: Some((-0.0, 10.0)),
            y_domain: Some((0.0, 10.0)),
            expand: true,
            clip: true,
        };
        let json = serde_json::to_string(&coord).expect("serialize -0.0 domain");
        let back: CoordKind = serde_json::from_str(&json).expect("deserialize");
        match back {
            CoordKind::Cartesian { x_domain, .. } => {
                let (x_lo, _) = x_domain.unwrap();
                // -0.0 == 0.0 in IEEE 754
                assert_eq!(x_lo, 0.0);
            }
            other => panic!("expected Cartesian, got {other:?}"),
        }
    }

    // ── Tick generation edge cases ────────────────────────────────────────

    /// A Tick with NaN pixel value would break SVG axis rendering.
    #[test]
    fn tick_nan_pixel_serializes_as_null() {
        let tick = Tick {
            value: 5.0,
            label: "5".to_string(),
            pixel: f64::NAN,
        };
        let json = serde_json::to_string(&tick).expect("serialize tick with NaN pixel");
        assert!(!json.contains("NaN"), "Tick pixel must not serialize as 'NaN': {json}");
    }

    /// Tick with infinity in value (edge case from log scale on zero input).
    #[test]
    fn tick_infinity_serializes_as_null() {
        let tick = Tick {
            value: f64::INFINITY,
            label: "Inf".to_string(),
            pixel: 500.0,
        };
        let json = serde_json::to_string(&tick).expect("serialize tick with Inf");
        assert!(!json.contains("Infinity"), "JSON must not contain 'Infinity': {json}");
    }

    /// TickLevel with empty ticks vec (what happens when domain is degenerate).
    #[test]
    fn tick_level_empty_ticks_round_trips() {
        let level = TickLevel {
            min_zoom: 1.0,
            max_zoom: 100.0,
            ticks: vec![],
        };
        let json = serde_json::to_string(&level).expect("serialize empty TickLevel");
        let back: TickLevel = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.ticks.len(), 0);
    }

    /// TickLevel with max_zoom = INFINITY should survive JSON round-trip.
    /// The zoom system uses INFINITY as "no upper limit" sentinel but
    /// serde_json serializes it as null, breaking deserialization.
    #[test]
    fn tick_level_infinity_max_zoom_round_trips() {
        let level = TickLevel {
            min_zoom: 1.0,
            max_zoom: f64::INFINITY,
            ticks: vec![],
        };
        let json = serde_json::to_string(&level).expect("serialize with Infinity");
        let back: TickLevel = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.ticks.len(), 0);
        assert!(back.max_zoom.is_infinite());
    }

    /// Tick with NaN value AND NaN pixel - the worst case from a broken scale.
    #[test]
    fn tick_all_nan_fields_serialize_without_panic() {
        let tick = Tick {
            value: f64::NAN,
            label: String::new(),
            pixel: f64::NAN,
        };
        let json = serde_json::to_string(&tick).expect("serialize all-NaN tick");
        assert!(!json.contains("NaN"), "JSON must not contain literal 'NaN': {json}");
    }

    /// Tick with empty label (degenerate case from tick formatter).
    #[test]
    fn tick_empty_label_round_trips() {
        let tick = Tick {
            value: 0.0,
            label: String::new(),
            pixel: 100.0,
        };
        let json = serde_json::to_string(&tick).expect("serialize empty-label tick");
        let back: Tick = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.label, "");
        assert_eq!(back.value, 0.0);
    }

