    // ── Numeric precision at scale boundaries ─────────────────────────────

    /// Verify that very precise coordinates survive JSON round-trip.
    #[test]
    fn circle_precise_coordinates_survive_round_trip() {
        let node = SceneNode::Circle {
            cx: 0.123456789012345,
            cy: 999.987654321098,
            r: 0.001,
            style: default_fill_stroke(),
        };
        let json = serde_json::to_string(&node).expect("serialize");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize");
        match back {
            SceneNode::Circle { cx, cy, r, .. } => {
                assert!(
                    (cx - 0.123456789012345).abs() < 1e-12,
                    "cx precision lost: {cx}"
                );
                assert!(
                    (cy - 999.987654321098).abs() < 1e-9,
                    "cy precision lost: {cy}"
                );
                assert!((r - 0.001).abs() < 1e-15, "r precision lost: {r}");
            }
            other => panic!("expected Circle, got {other:?}"),
        }
    }

    /// Path with subnormal coordinates.
    #[test]
    fn path_subnormal_coordinates_round_trip() {
        let node = SceneNode::Path {
            commands: vec![
                PathCmd::MoveTo { x: 1e-308, y: 1e-308 },
                PathCmd::LineTo { x: 5e-308, y: 5e-308 },
                PathCmd::Close,
            ],
            style: default_fill_stroke(),
            closed: true,
        };
        let json = serde_json::to_string(&node).expect("serialize subnormal path");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize");
        match &back {
            SceneNode::Path { commands, .. } => {
                match &commands[0] {
                    PathCmd::MoveTo { x, y } => {
                        assert!(*x > 0.0 && *x < 1e-307, "subnormal x lost: {x}");
                        assert!(*y > 0.0 && *y < 1e-307, "subnormal y lost: {y}");
                    }
                    other => panic!("expected MoveTo, got {other:?}"),
                }
            }
            other => panic!("expected Path, got {other:?}"),
        }
    }

    // ── Boundary: negative zero in coordinates ────────────────────────────

    /// Negative zero in circle coordinates should survive round-trip.
    #[test]
    fn circle_negative_zero_coordinates_round_trip() {
        let node = SceneNode::Circle {
            cx: -0.0,
            cy: -0.0,
            r: 5.0,
            style: default_fill_stroke(),
        };
        let json = serde_json::to_string(&node).expect("serialize -0.0 circle");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize");
        match back {
            SceneNode::Circle { cx, cy, .. } => {
                // -0.0 == 0.0 in IEEE 754
                assert_eq!(cx, 0.0);
                assert_eq!(cy, 0.0);
            }
            other => panic!("expected Circle, got {other:?}"),
        }
    }

    // ── Panel with many marks (stress test serialization) ────────────────

    /// Panel with 1000 circle marks should serialize and deserialize.
    #[test]
    fn panel_thousand_circles_round_trips() {
        let nodes: Vec<SceneNode> = (0..1000)
            .map(|i| SceneNode::Circle {
                cx: i as f64,
                cy: (i as f64).sqrt(),
                r: 3.0,
                style: default_fill_stroke(),
            })
            .collect();
        let batch = MarkBatch {
            kind: MarkBatchKind::Point,
            nodes,
            data_indices: None,
            tooltips: None,
            hrefs: None,
            descriptions: None,
            keys: None,
            blend: BlendMode::Normal,
            stroke_cap: None,
            stroke_join: None,
            packed_instances: None,
        };
        let panel = make_panel(vec![batch]);
        let json = serde_json::to_string(&panel).expect("serialize 1000 circles");
        let back: Panel = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.marks.len(), 1);
        assert_eq!(back.marks[0].nodes.len(), 1000);
    }

    // ── FillStroke edge cases ────────────────────────────────────────────

    /// FillStroke with zero opacity (invisible mark).
    #[test]
    fn fill_stroke_zero_opacity_round_trips() {
        let fs = FillStroke {
            fill: Some(Color::rgb(0, 0, 0)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 0.0,
            stroke_dash: None,
            stroke_opacity: 0.0,
            fill_opacity: 0.0,
            angle: 0.0,
        };
        let json = serde_json::to_string(&fs).expect("serialize zero-opacity");
        let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.opacity, 0.0);
        assert_eq!(back.fill_opacity, 0.0);
        assert_eq!(back.stroke_opacity, 0.0);
    }

    /// FillStroke with NaN opacity (what if color channel computation fails).
    #[test]
    fn fill_stroke_nan_opacity_serializes() {
        let fs = FillStroke {
            fill: None,
            stroke: None,
            stroke_width: 0.0,
            opacity: f64::NAN,
            stroke_dash: None,
            stroke_opacity: f64::NAN,
            fill_opacity: f64::NAN,
            angle: 0.0,
        };
        let json = serde_json::to_string(&fs).expect("serialize NaN opacity");
        assert!(!json.contains("NaN"), "FillStroke NaN must not appear as literal: {json}");
    }

    /// FillStroke with very long stroke dash pattern.
    #[test]
    fn fill_stroke_long_dash_pattern_round_trips() {
        let dashes: Vec<f64> = (0..100).map(|i| (i as f64) + 0.5).collect();
        let fs = FillStroke {
            fill: Some(Color::rgb(255, 0, 0)),
            stroke: Some(Color::rgb(0, 0, 255)),
            stroke_width: 2.0,
            opacity: 1.0,
            stroke_dash: Some(dashes.clone()),
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        };
        let json = serde_json::to_string(&fs).expect("serialize long dash");
        let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.stroke_dash.unwrap().len(), 100);
    }

